package com.texto.emailplatform.segment;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import com.texto.emailplatform.common.exception.ApiException; import com.texto.emailplatform.segment.api.*; import com.texto.emailplatform.segment.domain.*; import com.texto.emailplatform.tenant.web.TenantContext; import java.util.List; import java.util.UUID; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SegmentService {private final SegmentRepository segments;private final ObjectMapper json;private final SegmentConditionQueryBuilder queryBuilder; public SegmentService(SegmentRepository segments,ObjectMapper json,SegmentConditionQueryBuilder queryBuilder){this.segments=segments;this.json=json;this.queryBuilder=queryBuilder;}
 @Transactional public SegmentResponse create(SegmentRequest request){UUID tenant=tenant();String name=request.name().trim();if(segments.existsByTenantIdAndName(tenant,name))throw new ApiException(409,"SEGMENT_EXISTS","A segment with this name already exists");return response(segments.save(SegmentEntity.create(tenant,name,validate(request.definition()))));}
 @Transactional(readOnly=true) public List<SegmentResponse> list(){return segments.findByTenantIdOrderByUpdatedAtDesc(tenant()).stream().map(SegmentService::response).toList();}
 @Transactional public SegmentResponse update(UUID id,SegmentRequest request){SegmentEntity segment=require(id);if(!segment.getName().equals(request.name().trim()) && segments.existsByTenantIdAndName(tenant(),request.name().trim()))throw new ApiException(409,"SEGMENT_EXISTS","A segment with this name already exists");segment.update(request.name().trim(),validate(request.definition()));return response(segment);}
 @Transactional public void delete(UUID id){segments.delete(require(id));}
 private SegmentEntity require(UUID id){return segments.findByIdAndTenantId(id,tenant()).orElseThrow(()->new ApiException(404,"SEGMENT_NOT_FOUND","Segment was not found"));}
 private String validate(String definition){queryBuilder.build(definition);try{JsonNode root=json.readTree(definition);if(!root.isObject())throw new ApiException(400,"INVALID_SEGMENT","definition must be a JSON object");if(!root.has("operator")||!root.has("conditions"))throw new ApiException(400,"INVALID_SEGMENT","definition needs operator and conditions");String operator=root.path("operator").asText();if(!operator.equals("AND")&&!operator.equals("OR"))throw new ApiException(400,"INVALID_SEGMENT","operator must be AND or OR");if(!root.path("conditions").isArray())throw new ApiException(400,"INVALID_SEGMENT","conditions must be an array");return json.writeValueAsString(root);}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(HttpStatus.BAD_REQUEST.value(),"INVALID_SEGMENT","definition must be valid JSON");}}
 private static UUID tenant(){return TenantContext.get().orElseThrow(()->new ApiException(401,"UNAUTHENTICATED","Authentication is required"));}private static SegmentResponse response(SegmentEntity s){return new SegmentResponse(s.getId(),s.getName(),s.getDefinition(),s.getCreatedAt(),s.getUpdatedAt());}}
